SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(o),'identity',to_jsonb(pg_identify_object('pg_opfamily'::regclass,o.oid,0)),'owner',pg_get_userbyid(o.opfowner)) ORDER BY o.oid),'[]'::jsonb) AS payload FROM pg_opfamily o WHERE o.opfnamespace='public'::regnamespace OR o.oid IN (SELECT opc.opcfamily FROM pg_opclass opc WHERE opc.oid IN (SELECT unnest(indclass::oid[]) FROM pg_index WHERE indexrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)))) AS capture